'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
    DndContext,
    DragOverlay,
    DragStartEvent,
    DragEndEvent,
    MouseSensor,
    TouchSensor,
    useSensor,
    useSensors,
    pointerWithin,
    CollisionDetection,
    rectIntersection,
} from '@dnd-kit/core';
import { createPortal } from 'react-dom';
import { Package, Layout, Copy, Trash2, Users, Lock, Unlock, Ungroup } from 'lucide-react'; // Combined imports for lucide-react

import { PropositionType, Proposition, Vendor, Product, Solution, CanvasItem } from '@/lib/types';
import { CanvasSidebar } from '../CanvasSidebar';
import { CanvasWorkspace } from '../CanvasWorkspace';
import { PropertiesPanel } from '../PropertiesPanel';
import { useMultiSelect } from '@/hooks/useMultiSelect';
import { useKeyboardShortcuts } from '@/hooks/useKeyboardShortcuts';
import { useModifierKeys } from '@/hooks/useModifierKeys';
import { ContextMenu, ContextMenuAction } from '../controls/ContextMenu';
import { AlignmentToolbar } from '../controls/AlignmentToolbar';
import { SnapGuides, SnapGuide } from '../controls/SnapGuides';
import { GridToggle } from '../controls/GridToggle';
import { ThemeToggle } from '../controls/ThemeToggle';
import { alignItems, distributeItems } from '@/lib/utils/alignment';
import { useSnapToGrid } from '@/hooks/useSnapToGrid';
import { useTheme } from '@/hooks/useTheme';
import { Layers, AlignLeft, Grid } from 'lucide-react'; // Remaining lucide-react imports

// Custom collision strategy
const customCollisionStrategy: CollisionDetection = (args) => {
    const pointerCollisions = pointerWithin(args);
    if (pointerCollisions.length > 0) return pointerCollisions;
    const rectCollisions = rectIntersection(args);
    return rectCollisions.filter(c => c.id === 'canvas-droppable');
};

// Mock Data
const PROPOSITIONS: Proposition[] = [
    { id: 'digital-workspace', label: 'Digital Workspace' },
    { id: 'hybrid-cloud', label: 'Hybrid Cloud' },
    { id: 'artificial-intelligence', label: 'AI' },
    { id: 'cloud-native', label: 'Cloud Native' },
];

const VENDORS: Vendor[] = [
    { id: 'v-vmware', name: 'VMware' },
    { id: 'v-microsoft', name: 'Microsoft' },
    { id: 'v-aws', name: 'AWS' },
    { id: 'v-google', name: 'Google Cloud' },
];

const PRODUCTS: Product[] = [
    { id: 'p-vsphere', vendorId: 'v-vmware', propositionId: 'hybrid-cloud', name: 'vSphere' },
    { id: 'p-horizon', vendorId: 'v-vmware', propositionId: 'digital-workspace', name: 'Horizon' },
    { id: 'p-azure-vd', vendorId: 'v-microsoft', propositionId: 'digital-workspace', name: 'Azure Virtual Desktop' },
    { id: 'p-m365', vendorId: 'v-microsoft', propositionId: 'digital-workspace', name: 'Microsoft 365' },
    { id: 'p-openai', vendorId: 'v-microsoft', propositionId: 'artificial-intelligence', name: 'Azure OpenAI' },
    { id: 'p-eks', vendorId: 'v-aws', propositionId: 'cloud-native', name: 'Amazon EKS' },
];

const SOLUTIONS: Solution[] = [
    { id: 's-hybrid-workspace', name: 'Modern Hybrid Workspace', productIds: ['p-horizon', 'p-m365'] },
];

export function CanvasBoard() {
    // State with history for undo/redo
    const history = useHistory<CanvasItem[]>([]);
    const [activeDragData, setActiveDragData] = useState<any>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedProposition, setSelectedProposition] = useState<PropositionType | 'all'>('all');
    const [mounted, setMounted] = useState(false);
    const [debugInfo, setDebugInfo] = useState<string>('Ready');
    const [snapGuides, setSnapGuides] = useState<SnapGuide[]>([]);
    const [gridSnapEnabled, setGridSnapEnabled] = useState(false);

    const canvasRef = useRef<HTMLDivElement>(null);

    // Context Menu State
    const [contextMenu, setContextMenu] = useState<{ x: number, y: number, visible: boolean }>({ x: 0, y: 0, visible: false });

    // Grid snapping hook
    const gridSnap = useSnapToGrid({ enabled: gridSnapEnabled, gridSize: 20 });

    // Theme hook
    const { theme, toggleTheme, isDark } = useTheme();

    // Alignment handlers
    const handleAlign = (type: 'left' | 'center' | 'right' | 'top' | 'middle' | 'bottom') => {
        const selectedItems = items.filter(item => multiSelect.selectedIds.includes(item.id));
        if (selectedItems.length < 2) return;

        const aligned = alignItems({ type, items: selectedItems });
        setItems(prev => prev.map(item => {
            const alignedItem = aligned.find(a => a.id === item.id);
            return alignedItem || item;
        }));
        setDebugInfo(`Aligned ${selectedItems.length} items ${type}`);
    };

    const handleDistribute = (direction: 'horizontal' | 'vertical') => {
        const selectedItems = items.filter(item => multiSelect.selectedIds.includes(item.id));
        if (selectedItems.length < 3) return;

        const distributed = distributeItems({ direction, items: selectedItems });
        setItems(prev => prev.map(item => {
            const distributedItem = distributed.find(d => d.id === item.id);
            return distributedItem || item;
        }));
        setDebugInfo(`Distributed ${selectedItems.length} items ${direction}`);
    };

    // Multi-select hook
    const multiSelect = useMultiSelect();

    // Modifier keys
    const keys = useModifierKeys();

    useEffect(() => {
        setMounted(true);
    }, []);

    // Keyboard shortcuts
    useKeyboardShortcuts({
        onSelectAll: () => multiSelect.selectAll(items.map(i => i.id)),
        onDelete: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.filter(item => !selected.includes(item.id)));
                multiSelect.clearSelection();
                setDebugInfo(`Deleted ${selected.length} item(s)`);
            }
        },
        onDuplicate: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                const newItems = items
                    .filter(item => selected.includes(item.id))
                    .map(item => ({
                        ...item,
                        id: `item-${Date.now()}-${Math.random()}`,
                        x: item.x + 20,
                        y: item.y + 20
                    }));
                setItems(prev => [...prev, ...newItems]);
                setDebugInfo(`Duplicated ${selected.length} item(s)`);
            }
        },
        onEscape: () => multiSelect.clearSelection(),
        onNudgeUp: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, y: item.y - 1 } : item
                ));
            }
        },
        onNudgeDown: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, y: item.y + 1 } : item
                ));
            }
        },
        onNudgeLeft: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, x: item.x - 1 } : item
                ));
            }
        },
        onNudgeRight: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length > 0) {
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, x: item.x + 1 } : item
                ));
            }
        },
        onGroup: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length < 2) return;

            const selectedItems = items.filter(item => selected.includes(item.id));
            const allGrouped = selectedItems.every(it => it.groupId);

            if (allGrouped) {
                // Ungroup
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, groupId: undefined } : item
                ));
                setDebugInfo(`Ungrouped ${selected.length} items`);
            } else {
                // Group
                const groupId = `group-${Date.now()}`;
                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, groupId } : item
                ));
                setDebugInfo(`Grouped ${selected.length} items`);
            }
        },
        onLock: () => {
            const selected = multiSelect.selectedIds;
            if (selected.length === 0) return;

            const selectedItems = items.filter(item => selected.includes(item.id));
            const allLocked = selectedItems.every(it => it.locked);

            setItems(prev => prev.map(item =>
                selected.includes(item.id) ? { ...item, locked: !allLocked } : item
            ));
            setDebugInfo(`${allLocked ? 'Unlocked' : 'Locked'} ${selected.length} item(s)`);
        },
    }, mounted);

    const sensors = useSensors(
        useSensor(MouseSensor, { activationConstraint: { distance: 5 } }),
        useSensor(TouchSensor, { activationConstraint: { delay: 250, tolerance: 5 } })
    );

    // Prevent hydration mismatch
    if (!mounted) return (
        <div className="h-screen w-full bg-gray-950 flex items-center justify-center">
            <div className="w-8 h-8 rounded-full border-2 border-blue-500 border-t-transparent animate-spin" />
        </div>
    );

    // Handlers
    const handleDragStart = (event: DragStartEvent) => {
        setActiveDragData(event.active.data.current);
        setDebugInfo(`Dragging ${event.active.data.current?.label}...`);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveDragData(null);

        if (!over || over.id !== 'canvas-droppable') {
            setDebugInfo('Dropped outside canvas');
            return;
        }

        const canvasRect = canvasRef.current?.getBoundingClientRect();
        const sourceData = active.data.current;
        if (!sourceData) return;

        const droppedRect = active.rect.current.translated;
        let rawX = droppedRect ? (droppedRect.left - (canvasRect?.left ?? 0)) : 100;
        let rawY = droppedRect ? (droppedRect.top - (canvasRect?.top ?? 0)) : 100;

        // Apply grid snapping if enabled
        if (gridSnapEnabled) {
            const snapped = gridSnap.snapPosition(rawX, rawY);
            rawX = snapped.x;
            rawY = snapped.y;
        }

        // Clear snap guides
        setSnapGuides([]);

        if (sourceData.source === 'sidebar') {
            const newItem: CanvasItem = {
                id: `item-${Date.now()}`,
                entityId: sourceData.entityId,
                entityType: sourceData.type,
                x: rawX,
                y: rawY,
                data: sourceData
            };
            setItems(prev => [...prev, newItem]);
            multiSelect.selectMultiple([newItem.id]);
            setDebugInfo(`Added ${newItem.data.label}`);
        } else if (sourceData.source === 'canvas') {
            const draggedItem = items.find(it => it.id === active.id);
            if (!draggedItem) return;

            // Don't allow moving locked items
            if (draggedItem.locked) {
                setDebugInfo('Item is locked');
                return;
            }

            const isCopying = keys.ctrl || keys.alt;

            if (isCopying) {
                const newItemId = `item-${Date.now()}-${Math.random()}`;

                setItems(prev => {
                    const original = prev.find(it => it.id === active.id);
                    if (!original) return prev;

                    const newItem = {
                        ...original,
                        id: newItemId,
                        x: rawX,
                        y: rawY,
                        groupId: undefined // Remove from group when copying
                    };
                    return [...prev, newItem];
                });

                multiSelect.selectMultiple([newItemId]);
                setDebugInfo(`Copied item`);
            } else {
                // Calculate movement delta
                const deltaX = rawX - draggedItem.x;
                const deltaY = rawY - draggedItem.y;

                // Check if dragged item is part of multi-selection
                const isMultiSelected = multiSelect.selectedIds.includes(active.id as string) && multiSelect.selectedIds.length > 1;

                if (isMultiSelected) {
                    // Move all selected items together
                    setItems(prev => prev.map(it => {
                        if (multiSelect.selectedIds.includes(it.id) && !it.locked) {
                            return {
                                ...it,
                                x: it.x + deltaX,
                                y: it.y + deltaY
                            };
                        }
                        return it;
                    }));
                    setDebugInfo(`Moved ${multiSelect.selectedIds.length} selected items`);
                } else if (draggedItem.groupId) {
                    // Move all items in the same group
                    setItems(prev => prev.map(it => {
                        if (it.groupId === draggedItem.groupId && !it.locked) {
                            return {
                                ...it,
                                x: it.x + deltaX,
                                y: it.y + deltaY
                            };
                        }
                        return it;
                    }));
                    setDebugInfo(`Moved group`);
                } else {
                    // Move single item
                    setItems(prev => prev.map(it => {
                        if (it.id === active.id) {
                            return {
                                ...it,
                                x: rawX,
                                y: rawY
                            };
                        }
                        return it;
                    }));
                    setDebugInfo(`Moved item`);
                }
            }
        }
    };

    // Context Menu Actions
    const handleContextMenu = (e: React.MouseEvent) => {
        e.preventDefault();
        setContextMenu({ x: e.clientX, y: e.clientY, visible: true });
    };

    const contextMenuActions: ContextMenuAction[] = [
        {
            id: 'duplicate',
            label: 'Duplicate',
            icon: <Copy className="w-4 h-4" />,
            action: () => {
                const selected = multiSelect.selectedIds;
                if (selected.length > 0) {
                    const newItems = items
                        .filter(item => selected.includes(item.id))
                        .map(item => ({
                            ...item,
                            id: `item-${Date.now()}-${Math.random()}`,
                            x: item.x + 20,
                            y: item.y + 20
                        }));
                    setItems(prev => [...prev, ...newItems]);
                    setDebugInfo(`Duplicated ${selected.length} item(s)`);
                }
            },
            shortcut: 'Ctrl+D'
        },
        {
            id: 'group',
            label: multiSelect.selectedIds.length > 1 && items.filter(it => multiSelect.selectedIds.includes(it.id)).every(it => it.groupId) ? 'Ungroup' : 'Group',
            icon: multiSelect.selectedIds.length > 1 && items.filter(it => multiSelect.selectedIds.includes(it.id)).every(it => it.groupId) ? <Ungroup className="w-4 h-4" /> : <Users className="w-4 h-4" />,
            action: () => {
                const selected = multiSelect.selectedIds;
                if (selected.length < 2) return;

                const selectedItems = items.filter(item => selected.includes(item.id));
                const allGrouped = selectedItems.every(it => it.groupId);

                if (allGrouped) {
                    // Ungroup
                    setItems(prev => prev.map(item =>
                        selected.includes(item.id) ? { ...item, groupId: undefined } : item
                    ));
                    setDebugInfo(`Ungrouped ${selected.length} items`);
                } else {
                    // Group
                    const groupId = `group-${Date.now()}`;
                    setItems(prev => prev.map(item =>
                        selected.includes(item.id) ? { ...item, groupId } : item
                    ));
                    setDebugInfo(`Grouped ${selected.length} items`);
                }
            },
            disabled: multiSelect.selectedIds.length < 2
        },
        {
            id: 'lock',
            label: multiSelect.selectedIds.length > 0 && items.filter(it => multiSelect.selectedIds.includes(it.id)).every(it => it.locked) ? 'Unlock' : 'Lock',
            icon: multiSelect.selectedIds.length > 0 && items.filter(it => multiSelect.selectedIds.includes(it.id)).every(it => it.locked) ? <Unlock className="w-4 h-4" /> : <Lock className="w-4 h-4" />,
            action: () => {
                const selected = multiSelect.selectedIds;
                if (selected.length === 0) return;

                const selectedItems = items.filter(item => selected.includes(item.id));
                const allLocked = selectedItems.every(it => it.locked);

                setItems(prev => prev.map(item =>
                    selected.includes(item.id) ? { ...item, locked: !allLocked } : item
                ));
                setDebugInfo(`${allLocked ? 'Unlocked' : 'Locked'} ${selected.length} item(s)`);
            }
        },
        {
            id: 'delete',
            label: 'Delete',
            icon: <Trash2 className="w-4 h-4" />,
            action: () => {
                const selected = multiSelect.selectedIds;
                if (selected.length > 0) {
                    setItems(prev => prev.filter(item => !selected.includes(item.id)));
                    multiSelect.clearSelection();
                }
            },
            shortcut: 'Del',
            danger: true
        }
    ];

    // Filters
    const filteredProducts = PRODUCTS.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesProp = selectedProposition === 'all' || p.propositionId === selectedProposition;
        return matchesSearch && matchesProp;
    });

    const selectedItem = multiSelect.selectedIds.length === 1
        ? items.find(it => it.id === multiSelect.selectedIds[0])
        : undefined;
    const getVendorName = (vendorId: string) => VENDORS.find(v => v.id === vendorId)?.name;

    return (
        <DndContext
            id="qanvas-dnd-root"
            sensors={sensors}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
            collisionDetection={customCollisionStrategy}
        >
            <div
                className="flex h-screen w-full overflow-hidden"
                style={{
                    backgroundColor: 'var(--color-background)',
                    color: 'var(--color-text)'
                }}
                onContextMenu={handleContextMenu}
            >
                <CanvasSidebar
                    searchQuery={searchQuery}
                    onSearchChange={setSearchQuery}
                    selectedProposition={selectedProposition}
                    onPropositionChange={setSelectedProposition}
                    propositions={PROPOSITIONS}
                    filteredProducts={filteredProducts}
                    solutions={SOLUTIONS}
                    vendors={VENDORS}
                    getVendorName={getVendorName}
                />

                <CanvasWorkspace
                    canvasRef={canvasRef}
                    items={items}
                    selectedIds={multiSelect.selectedIds}
                    debugInfo={debugInfo}
                    vendors={VENDORS}
                    multiSelect={multiSelect}
                    onClearItems={() => {
                        setItems([]);
                        multiSelect.clearSelection();
                    }}
                />

                {contextMenu.visible && (
                    <ContextMenu
                        x={contextMenu.x}
                        y={contextMenu.y}
                        onClose={() => setContextMenu({ ...contextMenu, visible: false })}
                        actions={contextMenuActions}
                        selectedCount={multiSelect.selectedIds.length}
                    />
                )}

                <AlignmentToolbar
                    selectedCount={multiSelect.selectedIds.length}
                    onAlign={handleAlign}
                    onDistribute={handleDistribute}
                    onGroup={() => {
                        const selected = multiSelect.selectedIds;
                        if (selected.length < 2) return;

                        const selectedItems = items.filter(item => selected.includes(item.id));
                        const allGrouped = selectedItems.every(it => it.groupId);

                        if (allGrouped) {
                            setItems(prev => prev.map(item =>
                                selected.includes(item.id) ? { ...item, groupId: undefined } : item
                            ));
                            setDebugInfo(`Ungrouped ${selected.length} items`);
                        } else {
                            const groupId = `group-${Date.now()}`;
                            setItems(prev => prev.map(item =>
                                selected.includes(item.id) ? { ...item, groupId } : item
                            ));
                            setDebugInfo(`Grouped ${selected.length} items`);
                        }
                    }}
                    onLock={() => {
                        const selected = multiSelect.selectedIds;
                        if (selected.length === 0) return;

                        const selectedItems = items.filter(item => selected.includes(item.id));
                        const allLocked = selectedItems.every(it => it.locked);

                        setItems(prev => prev.map(item =>
                            selected.includes(item.id) ? { ...item, locked: !allLocked } : item
                        ));
                        setDebugInfo(`${allLocked ? 'Unlocked' : 'Locked'} ${selected.length} item(s)`);
                    }}
                    isGrouped={multiSelect.selectedIds.length > 0 && items.filter(it => multiSelect.selectedIds.includes(it.id)).every(it => it.groupId)}
                    isLocked={multiSelect.selectedIds.length > 0 && items.filter(it => multiSelect.selectedIds.includes(it.id)).every(it => it.locked)}
                />

                <SnapGuides
                    guides={snapGuides}
                    canvasRect={canvasRef.current?.getBoundingClientRect()}
                />

                <GridToggle
                    enabled={gridSnapEnabled}
                    onToggle={() => setGridSnapEnabled(!gridSnapEnabled)}
                />

                <ThemeToggle
                    isDark={isDark}
                    onToggle={toggleTheme}
                />

                <PropertiesPanel
                    selectedItem={selectedItem}
                    selectedCount={multiSelect.selectedCount}
                    propositions={PROPOSITIONS}
                    vendors={VENDORS}
                />
            </div>

            {mounted && createPortal(
                <DragOverlay dropAnimation={null}>
                    {activeDragData ? (
                        <div
                            className="p-4 w-60 rounded-2xl border shadow-2xl scale-105 opacity-90 z-[100] cursor-grabbing pointer-events-none"
                            style={{
                                borderColor: 'var(--color-primary)',
                                backgroundColor: 'var(--color-surface)',
                                boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)'
                            }}
                        >
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-blue-500/20 text-blue-500 flex items-center justify-center">
                                    {activeDragData.type === 'product' ? <Package className="w-5 h-5" /> : <Layout className="w-5 h-5" />}
                                </div>
                                <div className="flex flex-col">
                                    <span
                                        className="text-sm font-bold"
                                        style={{ color: 'var(--color-text)' }}
                                    >
                                        {activeDragData.label}
                                    </span>
                                    <span
                                        className="text-[10px] uppercase tracking-widest"
                                        style={{ color: 'var(--color-text-muted)' }}
                                    >
                                        Dropping...
                                    </span>
                                </div>
                            </div>
                        </div>
                    ) : null}
                </DragOverlay>,
                document.body
            )}
        </DndContext>
    );
}
