import React from 'react';

export interface SnapGuide {
    type: 'vertical' | 'horizontal';
    position: number;
    items: string[]; // IDs of items that are aligned
}

export interface SnapGuidesProps {
    guides: SnapGuide[];
    canvasRect?: DOMRect | null;
}

export function SnapGuides({ guides, canvasRect }: SnapGuidesProps) {
    if (!canvasRect || guides.length === 0) return null;

    return (
        <div className="absolute inset-0 pointer-events-none z-40">
            {guides.map((guide, index) => {
                const key = `${guide.type}-${guide.position}-${index}`;

                if (guide.type === 'vertical') {
                    return (
                        <div
                            key={key}
                            className="absolute top-0 bottom-0 w-px bg-red-500 animate-pulse"
                            style={{
                                left: `${guide.position}px`,
                                boxShadow: '0 0 4px rgba(239, 68, 68, 0.5)'
                            }}
                        />
                    );
                } else {
                    return (
                        <div
                            key={key}
                            className="absolute left-0 right-0 h-px bg-red-500 animate-pulse"
                            style={{
                                top: `${guide.position}px`,
                                boxShadow: '0 0 4px rgba(239, 68, 68, 0.5)'
                            }}
                        />
                    );
                }
            })}
        </div>
    );
}
